&lt;div style="max-width: 1200px; margin: 40px auto;"&gt;
  &lt;p&gt;
    I am a hobbyist photographer, virtual pilot, and S1-trainee air traffic controller with VATUSA,
    &lt;a href="https://www.vatsim.net" target="_blank"&gt;VATSIM&lt;/a&gt;'s United States Division.
  &lt;/p&gt;
  &lt;hr&gt;
  &lt;p&gt;A collection of my photos&lt;/p&gt;
  &lt;div id="photo-gallery" style="columns: 2; column-gap: 15px; max-width: 900px; margin: auto;"&gt;
    ${photos.map(p =&gt; html`
      &lt;figure style="break-inside: avoid; margin: 0 0 15px 0; ${p.span ? "column-span: all;" : ""}"&gt;
        &lt;a href="${p.file}" target="_blank"&gt;
          &lt;img src="${p.file}" style="width:100%;" loading="lazy"&gt;
        &lt;/a&gt;
        &lt;figcaption style="text-align:center; color:gray; font-size:0.90rem;"&gt;${p.caption}&lt;/figcaption&gt;
      &lt;/figure&gt;
    `)}
  &lt;/div&gt;
&lt;/div&gt;`
